import{_ as t,o as r,c as n,a2 as i}from"./chunks/framework.Buc7gXeZ.js";const c=JSON.parse('{"title":"Gestaltung","description":"Farben, Logo, Hintergrundbild und Feldstil eines Formulars anpassen.","frontmatter":{"title":"Gestaltung","description":"Farben, Logo, Hintergrundbild und Feldstil eines Formulars anpassen."},"headers":[],"relativePath":"formulare/gestaltung.md","filePath":"formulare/gestaltung.md","lastUpdated":1786088012000}'),a={name:"formulare/gestaltung.md"};function s(l,e,d,o,u,g){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="gestaltung" tabindex="-1">Gestaltung <a class="header-anchor" href="#gestaltung" aria-label="Permalink to &quot;Gestaltung&quot;">​</a></h1><p>Im Reiter <strong>Layout</strong> des Formular-Editors passen Sie das Erscheinungsbild an. Die Einstellungen sind in vier Abschnitte gegliedert.</p><h2 id="texte" tabindex="-1">Texte <a class="header-anchor" href="#texte" aria-label="Permalink to &quot;Texte&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Titel des Formulars</strong></td><td>Überschrift, Platzhalter <em>Titel hinzufügen…</em></td></tr><tr><td><strong>Beschreibung</strong></td><td>Einleitungstext, Platzhalter <em>Beschreibung hinzufügen…</em></td></tr><tr><td><strong>Absenden-Button Text</strong></td><td>Beschriftung des Absende-Buttons</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Der Button-Text darf konkret sein</p><p><em>Absenden</em> ist neutral, aber nichtssagend. <em>Anmeldung abschicken</em>, <em>Termin anfragen</em> oder <em>Störung melden</em> sagt Ausfüllenden, was gleich passiert — und erhöht die Abschlussquote.</p></div><h2 id="bilder-und-logo" tabindex="-1">Bilder und Logo <a class="header-anchor" href="#bilder-und-logo" aria-label="Permalink to &quot;Bilder und Logo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Hintergrundbild</strong></td><td>Bild im Kopfbereich des Formulars</td></tr><tr><td><strong>Logo</strong></td><td>Eigenes Logo über dem Formular</td></tr><tr><td><strong>Breite</strong></td><td>Logobreite in Prozent der Formularbreite</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Das Logo ist tarifabhängig</p><p>Ein eigenes Logo steht nur im höchsten Tarif zur Verfügung. Hintergrundbild und Farben sind in allen Tarifen verfügbar.</p></div><div class="tip custom-block"><p class="custom-block-title">Logobreite konservativ wählen</p><p>Die Angabe ist ein Prozentsatz der Formularbreite, keine Pixelgröße. Werte um 20 bis 30 Prozent wirken auf Mobilgeräten meist besser als große Logos, die dort den halben Bildschirm einnehmen.</p></div><h2 id="farben" tabindex="-1">Farben <a class="header-anchor" href="#farben" aria-label="Permalink to &quot;Farben&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkt auf</th></tr></thead><tbody><tr><td><strong>Hauptfarbe</strong></td><td>Akzente im Formular</td></tr><tr><td><strong>Button Farbe</strong></td><td>Absende-Button</td></tr><tr><td><strong>Hintergrundfarbe</strong></td><td>Fläche hinter dem Formular</td></tr><tr><td><strong>Hintergrundfarbe Karte</strong></td><td>Fläche des Formulars selbst</td></tr><tr><td><strong>Farbe Kopfzeile</strong></td><td>Kopfbereich</td></tr><tr><td><strong>Karte ohne Schatten</strong></td><td>Entfernt den Schlagschatten</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Zwei Farben genügen meist</p><p>Hauptfarbe und Button-Farbe reichen für ein stimmiges Ergebnis. Werden alle sechs Einstellungen unterschiedlich gesetzt, wirkt das Formular schnell unruhig.</p><p>Achten Sie auf <strong>Kontrast</strong>: Heller Text auf hellem Hintergrund ist auf Mobilgeräten im Sonnenlicht unlesbar.</p></div><h2 id="style-der-felder" tabindex="-1">Style der Felder <a class="header-anchor" href="#style-der-felder" aria-label="Permalink to &quot;Style der Felder&quot;">​</a></h2><p>Zwei Möglichkeiten:</p><table tabindex="0"><thead><tr><th>Auswahl</th><th>Darstellung</th></tr></thead><tbody><tr><td><strong>Ohne Rahmen</strong></td><td>Beschriftung wandert beim Tippen nach oben</td></tr><tr><td><strong>Mit Rahmen</strong></td><td>Beschriftung steht fest über dem umrandeten Feld</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Mit Rahmen ist meist die sicherere Wahl</p><p>Bei <em>Ohne Rahmen</em> ist die Beschriftung zunächst im Feld — manche Ausfüllende halten sie für einen bereits eingetragenen Wert. Bei längeren Formularen mit vielen Feldern ist <em>Mit Rahmen</em> eindeutiger.</p></div><h2 id="produkthinweis-ausblenden" tabindex="-1">Produkthinweis ausblenden <a class="header-anchor" href="#produkthinweis-ausblenden" aria-label="Permalink to &quot;Produkthinweis ausblenden&quot;">​</a></h2><p>Formulare tragen standardmäßig den Hinweis <em>Erstell dein eigenes kostenloses Formular mit …</em>. Über <strong>Produkt Hinweis ausblenden</strong> entfernen Sie ihn.</p><p>Tarifabhängig.</p><h2 id="erscheinungsbild-prufen" tabindex="-1">Erscheinungsbild prüfen <a class="header-anchor" href="#erscheinungsbild-prufen" aria-label="Permalink to &quot;Erscheinungsbild prüfen&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">In beiden Breiten ansehen</p><p>Über <strong>Vorschau in neuem Tab</strong> sehen Sie das Formular wie Ausfüllende. Verkleinern Sie das Fenster auf Smartphone-Breite — dort fallen zu große Logos, schlechte Kontraste und überlange Beschriftungen zuerst auf.</p><p>Beim Einbetten gibt es zusätzlich <em>Vorschau Smartphone</em> und <em>Vorschau Computer</em>. → <a href="/docs/formulare/formular-teilen">Formular teilen</a></p></div><h2 id="grenzen-der-gestaltung" tabindex="-1">Grenzen der Gestaltung <a class="header-anchor" href="#grenzen-der-gestaltung" aria-label="Permalink to &quot;Grenzen der Gestaltung&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Was im Formular nicht geht</p><ul><li><strong>Kein eigenes CSS</strong>, keine freie Positionierung</li><li><strong>Keine bedingte Anzeige</strong> von Feldern</li><li><strong>Kein mehrspaltiges Layout</strong> — Felder stehen untereinander</li></ul><p>Brauchen Sie das, ist eine <a href="/docs/seiten/was-sind-seiten">Seite</a> das richtige Werkzeug: Dort gibt es Layout-Blöcke, HTML und <a href="/docs/seiten/sichtbarkeit">bedingte Sichtbarkeit</a>.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/formulare/felder-konfigurieren">Felder konfigurieren</a></li><li><a href="/docs/formulare/erfolgsseite">Erfolgsseite und Weiterleitung</a></li><li><a href="/docs/formulare/formular-teilen">Formular teilen</a></li></ul>',25)])])}const b=t(a,[["render",s]]);export{c as __pageData,b as default};
